CREATE TABLE personal_goals(id INTEGER PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'personal', horizon TEXT NOT NULL DEFAULT 'short', due_date TEXT, notes TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','paused','done')), depends_on INTEGER REFERENCES personal_goals(id) ON DELETE SET NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE personal_goal_steps(id INTEGER PRIMARY KEY, goal_id INTEGER NOT NULL REFERENCES personal_goals(id) ON DELETE CASCADE, title TEXT NOT NULL, due_date TEXT, is_milestone INTEGER NOT NULL DEFAULT 0 CHECK(is_milestone IN (0,1)), status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','done')), depends_on INTEGER REFERENCES personal_goal_steps(id) ON DELETE SET NULL, sort INTEGER NOT NULL DEFAULT 0);
CREATE INDEX personal_goal_step_parent ON personal_goal_steps(goal_id,sort,id);
